    """Follow "next" from page 1 until it is null. Returns the page dicts in order."""
    pages = []
    total_pages = None
    page_no = 1
    path = "/orders?page=1"
    while True:
        data = api.call("GET", path)
        if not isinstance(data, dict) or data.get("page") != page_no or not isinstance(data.get("items"), list):
            raise RuntimeError(f"page {page_no}: unexpected body {str(data)[:200]}")
        if total_pages is None:
            total_pages = data["total_pages"]
        if data["total_pages"] != total_pages:
            raise RuntimeError(f"total_pages changed from {total_pages} to {data['total_pages']} at page {page_no}")
        with open(f"{RAW_DIR}/orders-page-{page_no:03d}.json", "w", encoding="utf-8") as f:
            json.dump(data, f)
        pages.append(data)
        log(f"page {page_no}/{total_pages}: {len(data['items'])} items, next={data['next']!r}")
        nxt = data["next"]
        if nxt is None:
            if page_no != total_pages:
                raise RuntimeError(f"listing ended at page {page_no} of {total_pages}")
            return pages
        if nxt != f"/orders?page={page_no + 1}":
            raise RuntimeError(f"page {page_no}: next is {nxt!r}, expected /orders?page={page_no + 1}")
        path = nxt
        page_no += 1


def fetch_customers(api, customer_ids):
    customers = {}
    for cid in sorted(customer_ids):
        record = api.call("GET", f"/customers/{cid}", missing_ok=True)
        if record is None:
            raise RuntimeError(f"customer {cid} returned 404 three times")
        if (
            record.get("id") != cid
            or record.get("region") not in REGIONS
            or not isinstance(record.get("discount_pct"), int)
            or not 0 <= record["discount_pct"] <= 100
        ):
            raise RuntimeError(f"customer {cid} has an unexpected record: {record}")
        customers[cid] = record
    with open(f"{RAW_DIR}/customers.json", "w", encoding="utf-8") as f:
        json.dump(customers, f)
    log(f"fetched {len(customers)} customer records")
    return customers


def well_formed(item):
    return (
        isinstance(item, dict)
        and all(isinstance(item.get(k), str) for k in ("id", "customer_id", "status", "placed_at"))
        and isinstance(item.get("amount_cents"), int)
        and not isinstance(item.get("amount_cents"), bool)
        and item["amount_cents"] >= 0
    )


def utc(ts):
    return dt.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(dt.timezone.utc)


def main():
    api = Api()
    api.new_token()
    pages = fetch_orders(api)

    sizes = [len(p["items"]) for p in pages]
    if any(s != 50 for s in sizes[:-1]) or not 0 < sizes[-1] <= 50:
        raise RuntimeError(f"unexpected page sizes {sizes}")

    listings = [(page_no, item) for page_no, page in enumerate(pages, start=1) for item in page["items"]]
    bad = [item for _, item in listings if not well_formed(item)]
    if bad:
        raise RuntimeError(f"{len(bad)} malformed listing entries, first: {bad[0]}")
    bad_ts = [item["placed_at"] for _, item in listings if not TIMESTAMP.fullmatch(item["placed_at"])]
    if bad_ts:
        raise RuntimeError(f"{len(bad_ts)} timestamps not in the expected format, e.g. {bad_ts[:3]}")
    offsets = Counter("Z" if item["placed_at"].endswith("Z") else item["placed_at"][-6:] for _, item in listings)
    log(f"timestamp offsets seen: {dict(offsets)}")

    copies = defaultdict(list)
    for page_no, item in listings:
        copies[item["id"]].append((page_no, item))
    conflicting = [oid for oid, c in copies.items() if any(it != c[0][1] for _, it in c)]
    if conflicting:
        raise RuntimeError(f"repeated order ids with differing content, e.g. {conflicting[:3]}")
    distinct = {oid: c[0][1] for oid, c in copies.items()}
    duplicates_skipped = len(listings) - len(distinct)
    repeated = {oid: [p for p, _ in c] for oid, c in copies.items() if len(c) > 1}
    log(f"{len(listings)} listings, {len(distinct)} distinct orders, {duplicates_skipped} repeated listings")
    log(f"repeated ids and the pages they appeared on: {repeated}")
    log(f"statuses among distinct orders: {dict(Counter(o['status'] for o in distinct.values()))}")

    qualifying = [
        o
        for o in distinct.values()
        if o["status"] == "shipped" and RANGE_START <= utc(o["placed_at"]) < RANGE_END
    ]
    log(f"{len(qualifying)} qualifying orders (shipped, 1 Mar to 31 May 2025 UTC)")

    customers = fetch_customers(api, {o["customer_id"] for o in qualifying})

    total = 0
    by_region = {r: 0 for r in REGIONS}
    for o in qualifying:
        c = customers[o["customer_id"]]
        discounted = Fraction(o["amount_cents"] * (100 - c["discount_pct"]), 100)
        cents = math.floor(discounted + Fraction(1, 2))  # half up, per order
        total += cents
        by_region[c["region"]] += cents

    if sum(by_region.values()) != total:
        raise RuntimeError("by_region does not add up to total_cents")
    if len({o["id"] for o in qualifying}) != len(qualifying):
        raise RuntimeError("an order was counted twice")

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    with open(RESULT_PATH, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    log(f"wrote {RESULT_PATH}: {json.dumps(result)}")
    log(f"api counts: {dict(api.counts)}")


if __name__ == "__main__":
    main()
